export type UserInputWritable = {
  /**
   * Unique username (alphanumeric only)
   */
  username: string
  full_name: string
  /**
   * User password. Must satisfy the configured local password policy:
   * at least `BABBEL_AUTH_MIN_PASSWORD_LENGTH` characters (`too_short`),
   * at most 72 bytes in UTF-8 (`too_long`), and the configured
   * character classes (`invalid_format`).
   *
   */
  password: string
  /**
   * Omit or set to null to create user without email
   */
  email?: string | null
  /**
   * User roles and permissions:
   * - admin: Full access to all resources including user management
   * - editor: Can manage content (stations, voices, stories, bulletins)
   * - viewer: Read-only access to content
   *
   */
  role: 'admin' | 'editor' | 'viewer'
  /**
   * JSON metadata object for user-specific settings (optional)
   */
  metadata?: {
    [key: string]: unknown
  }
}

/**
 * All fields are optional - only provided fields will be updated. Null is
 * treated as omit. At least one non-null field must be provided; an
 * object containing only null values is rejected.
 *
 */
export type UserUpdateWritable = {
  /**
   * Unique username (alphanumeric only). Null is treated as omit.
   */
  username?: string | null
  /**
   * Null is treated as omit.
   */
  full_name?: string | null
  /**
   * New password. Must satisfy the configured local password policy
   * (see `UserInput.password`); at most 72 bytes in UTF-8. Null is
   * treated as omit.
   *
   */
  password?: string | null
  /**
   * New email address. Set to an empty string ("") to clear the stored
   * email address. Null (or omitting the field) leaves the email
   * unchanged.
   *
   */
  email?: string | '' | null
  /**
   * Null is treated as omit.
   */
  role?: 'admin' | 'editor' | 'viewer' | null
  metadata?: {
    [key: string]: unknown
  } | null
  /**
   * Set to true to suspend user, false to restore
   */
  suspended?: boolean | null
}

/**
 * Resource ID. Must be a positive integer. A malformed ID is rejected
 * with 422 Unprocessable Entity (`errors[].field` is `id`, code
 * `invalid_format`); a zero, negative or too large ID with code
 * `out_of_range`.
 *
 */
export type id = number

/**
 * Byte-range request (e.g. `bytes=0-1023`). Audio file responses support
 * byte ranges; a satisfiable range returns 206 Partial Content and an
 * unsatisfiable range returns 416 Range Not Satisfiable.
 *
 */
export type rangeHeader = string

/**
 * Conditional request based on the file modification time (HTTP-date).
 * When the audio file has not changed since the given time, the server
 * responds 304 Not Modified. `If-None-Match` is not supported because
 * audio responses carry no ETag.
 *
 */
export type ifModifiedSinceHeader = string

/**
 * Maximum number of items to return. Values below 1, above 100, or
 * non-integer values are rejected with 422 Unprocessable Entity.
 *
 */
export type limit = number

/**
 * Number of items to skip. Negative or non-integer values are rejected
 * with 422 Unprocessable Entity.
 *
 */
export type offset = number

/**
 * Sort order. Use field:direction format or prefix notation:
 * - `name:asc` or `+name` - ascending
 * - `name:desc` or `-name` - descending
 * - `created_at:desc,name:asc` - multiple fields
 *
 * An empty value means the default order. An empty item (`sort=,`,
 * `sort=name,`) or an item without a field name (`sort=-`,
 * `sort=:desc`) fails with 422 `invalid_format`.
 *
 * Text fields sort by the database column collation, not by code point.
 * With MySQL's default collation `utf8mb4_0900_ai_ci` (8.0 and later),
 * case and accents do not count: `apple` sorts before `Banana`, and
 * `delta` equals `Delta`. Rows with equal values, also under the default
 * sort, have no defined order and can repeat or go missing across pages;
 * add `id` as the last sort field for a stable order.
 *
 */
export type sort = string

/**
 * Comma-separated list of top-level JSON field names to include in the
 * response (sparse fieldsets). Field names match the JSON response
 * properties exactly (e.g. `id,name,created_at`). Nested or dot
 * notation (e.g. `station.name`) is not supported. When this parameter
 * is used, response objects contain only the requested fields; all
 * other documented fields (including required ones) are omitted, so a
 * sparse response is a subset projection that intentionally does not
 * conform to the full resource schema. An empty value returns all
 * fields; an empty item (`fields=,`, `fields=id,,name`) fails with 422
 * `invalid_format`.
 *
 */
export type fields = string

/**
 * Literal substring match on any of the operation's fields listed
 * under "Search Fields" (`%` and `_` are not wildcards); case
 * sensitivity follows the column collation (case-insensitive by
 * default).
 *
 */
export type search = string

/**
 * Filter soft-deleted records:
 * - (omitted) - only non-deleted records (default)
 * - `only` - only soft-deleted records
 * - `with` - all records including deleted
 *
 */
export type trashed = 'only' | 'with'

